package dev.veltraph.client.navigation;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class SharedMovementExpectedAckWindowTest {
    final SharedMovementCoordinator.Lease owner=SharedMovementCoordinatorTest.lease();final Object journey=new Object();
    final Vec3 goal=new Vec3(8,70,0);final Object domain=new Object();
    SharedMovementCoordinator.Issue issue(Object token,long base){return new SharedMovementCoordinator.Issue(token,domain,base,100,true);}
    SharedMovementCoordinator.AppliedReceipt applied(SharedMovementCoordinator.Issue i,long serial,Vec3 position){return new SharedMovementCoordinator.AppliedReceipt(i.token(),i.receiptDomain(),serial,110,position,owner.player(),owner.world(),owner.connection());}
    @Test void qualifiedRetiredReceiptCanBeConsumedOnce(){var w=new SharedMovementExpectedAckWindow();var i=issue(new Object(),20);assertTrue(w.retain(owner,journey,i,applied(i,21,goal),goal,.30,500));assertTrue(w.consume(owner,journey,goal,120,21));assertFalse(w.consume(owner,journey,goal,121,21));}
    @Test void twoDistinctActualIssuesDoNotReuseNonceOrBaseline(){var w=new SharedMovementExpectedAckWindow();var a=issue(new Object(),20);var b=issue(new Object(),21);var second=new Vec3(16,70,0);assertTrue(w.retain(owner,journey,a,applied(a,21,goal),goal,.30,500));assertTrue(w.consume(owner,journey,goal,120,21));assertTrue(w.retain(owner,journey,b,applied(b,22,second),second,.30,500));assertTrue(w.consume(owner,journey,second,130,22));assertFalse(w.consume(owner,journey,second,131,22));assertNotSame(a.token(),b.token());assertTrue(b.baseline()>a.baseline());}
    @Test void noRawReceiptCanAuthorizeWithoutQualifiedRetainedIssue(){var w=new SharedMovementExpectedAckWindow();assertFalse(w.consume(owner,journey,goal,120,99));}
    @Test void supersedingNativePacketVetoesOldAcceptedReceipt(){var w=new SharedMovementExpectedAckWindow();var i=issue(new Object(),20);w.retain(owner,journey,i,applied(i,21,goal),goal,.30,500);assertFalse(w.consume(owner,journey,goal,120,22));}
    @Test void foreignJourneyOrLeaseCannotConsume(){var w=new SharedMovementExpectedAckWindow();var i=issue(new Object(),20);w.retain(owner,journey,i,applied(i,21,goal),goal,.30,500);assertFalse(w.consume(owner,new Object(),goal,120,21));assertFalse(w.consume(SharedMovementCoordinatorTest.lease(),journey,goal,120,21));}
    @Test void staleFutureAndForeignPositionsCannotConsume(){var w=new SharedMovementExpectedAckWindow();var i=issue(new Object(),20);w.retain(owner,journey,i,applied(i,21,goal),goal,.30,500);assertFalse(w.consume(owner,journey,goal,109,21));assertFalse(w.consume(owner,journey,goal,500,21));assertFalse(w.consume(owner,journey,new Vec3(8.1,70,0),120,21));}
    @Test void invalidIssueDomainsBaselinesAndBodiesNeverEnterWindow(){var w=new SharedMovementExpectedAckWindow();var i=issue(new Object(),20);assertFalse(w.retain(owner,journey,i,applied(i,20,goal),goal,.30,500));var forged=new SharedMovementCoordinator.AppliedReceipt(new Object(),domain,21,110,goal,owner.player(),owner.world(),owner.connection());assertFalse(w.retain(owner,journey,i,forged,goal,.30,500));var foreign=new SharedMovementCoordinator.AppliedReceipt(i.token(),domain,21,110,goal,new Object(),owner.world(),owner.connection());assertFalse(w.retain(owner,journey,i,foreign,goal,.30,500));assertFalse(w.retain(owner,journey,new SharedMovementCoordinator.Issue(i.token(),domain,20,100,false),applied(i,21,goal),goal,.30,500));assertEquals(0,w.size());}
    @Test void boundedWindowAndDuplicateRetainCannotRearmConsumption(){var w=new SharedMovementExpectedAckWindow();var a=issue(new Object(),20);var b=issue(new Object(),21);var c=issue(new Object(),22);assertTrue(w.retain(owner,journey,a,applied(a,21,goal),goal,.30,500));assertTrue(w.consume(owner,journey,goal,120,21));assertTrue(w.retain(owner,journey,a,applied(a,21,goal),goal,.30,500));assertFalse(w.consume(owner,journey,goal,121,21));assertTrue(w.retain(owner,journey,b,applied(b,22,goal),goal,.30,500));assertFalse(w.retain(owner,journey,c,applied(c,23,goal),goal,.30,500));assertEquals(2,w.size());w.clear();assertFalse(w.consume(owner,journey,goal,122,22));assertEquals(0,w.size());}
}
